Assume POSIX semantics, that every call succeeds, and that `f.txt` does not exist initially. Writes past the current end extend the file; writes inside it overwrite.

```c
int fd = open("f.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);
write(fd, "ABCDEF", 6);
int a = open("f.txt", O_WRONLY | O_APPEND);
int d = dup(fd);
lseek(fd, 2, SEEK_SET);
if (fork() == 0) {
    write(d, "xy", 2);
    write(a, "Q", 1);
    int g = open("f.txt", O_WRONLY);
    write(g, "zz", 2);
    lseek(fd, 0, SEEK_END);
    exit(0);
}
wait(NULL);
write(fd, "M", 1);
write(a, "N", 1);
write(d, "P", 1);
```

What are the final contents of `f.txt`?

