```c
int main(void) {
    for (int i = 1; i <= 5; i++) {
        if (fork() == 0) {     // child i
            sleep(i);         // child i exits at t ≈ i seconds
            exit(0);
        }
    }
    wait(NULL);
    wait(NULL);
    sleep(100);
    return 0;
}
```

